ccm.append('  return <span className={"ccm-product-badge inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold " + (cols[type] || "bg-gray-100 text-gray-700")}>{type.replace(/_/g, " ")}</span>')
ccm.append('}')
ccm.append('')
ccm.append('function StatusBadge({ status }: { status: string }) {')
