ccm.append('  return <span className={"ccm-status-badge inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold " + (cols[status] || "")}>{status.replace(/_/g, " ")}</span>')
ccm.append('}')
ccm.append('')
ccm.append('function ColdBadge({ type }: { type: string }) {')
ccm.append('  const cols: Record<string, string> = { chilled: "bg-blue-100 text-blue-700", frozen: "bg-cyan-100 text-cyan-700 dark:bg-cyan-900/30", ambient_controlled: "bg-emerald-100 text-emerald-700", deep_frozen: "ccm-deep-frozen bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30", ultra_cold: "ccm-ultra-cold bg-violet-100 text-violet-700 dark:bg-violet-900/30" }')
ccm.append('  return <span className={"ccm-cold-badge inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-bold " + (cols[type] || "")}>{type.replace(/_/g, " ")}</span>')
ccm.append('}')
ccm.append('')
ccm.append('function TempBandBadge({ band }: { band: string }) {')
ccm.append('  const cols: Record<string, string> = { optimal: "bg-emerald-100 text-emerald-700", warning: "bg-amber-100 text-amber-700", critical: "bg-orange-100 text-orange-700 dark:bg-orange-900/30", breach: "ccm-breach bg-red-100 text-red-700 dark:bg-red-900/30 shadow-[0_0_8px_rgba(220,38,38,0.4)]" }')
ccm.append('  return <span className={"ccm-temp-band-badge inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-bold uppercase " + (cols[band] || "")}>{band}</span>')
ccm.append('}')
ccm.append('')
ccm.append('function TempGauge({ current, min, max }: { current: number; min: number; max: number }) {')
ccm.append('  const range = max - min')
ccm.append('  const pct = Math.round(((current - min) / range) * 100)')
ccm.append('  const isOk = current >= min && current <= max')
ccm.append('  const col = isOk ? TH.ok : current < min ? "#3b82f6" : TH.err')
ccm.append('  return <div className="ccm-temp-gauge flex items-center gap-1.5"><Thermometer className="w-3 h-3" style={{ color: col }}/><span className={"text-[10px] font-bold " + (isOk ? "" : "text-red-600")}>{current}&deg;C</span><span className="text-[9px] text-gray-400">({min}&deg;-{max}&deg;C)</span></div>')
ccm.append('}')
ccm.append('')
ccm.append('function HumidityBar({ value }: { value: number }) {')
ccm.append('  const col = value <= 30 ? TH.err : value >= 80 ? TH.warn : TH.ok')
ccm.append('  return <div className="ccm-humidity-bar flex items-center gap-1.5"><div className="w-14 h-2 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden"><div className="h-full rounded-full transition-all" style={{ width: value + "%", backgroundColor: col }}/></div><span className="text-[10px] font-semibold" style={{ color: col }}>{value}%</span></div>')
ccm.append('}')
ccm.append('')
ccm.append('function HealthRing({ pct, label, color }: { pct: number; label: string; color: string }) {')
ccm.append('  const r = 28, c = 2 * Math.PI * r, off = c - (pct / 100) * c')
ccm.append('  return <div className="ccm-health-ring flex flex-col items-center"><svg width="68" height="68" viewBox="0 0 68 68"><circle cx="34" cy="34" r={r} fill="none" stroke="#e5e7eb" strokeWidth="6"/><circle cx="34" cy="34" r={r} fill="none" stroke={color} strokeWidth="6" strokeDasharray={c} strokeDashoffset={off} strokeLinecap="round" transform="rotate(-90 34 34)" className="transition-all duration-700"/><text x="34" y="38" textAnchor="middle" className="text-[11px] font-bold" fill={color}>{pct}%</text></svg><span className="text-[9px] text-gray-500 mt-0.5">{label}</span></div>')
ccm.append('}')
ccm.append('')
ccm.append('function KpiTile({ label, value, change, icon: Icon }: { label: string; value: string; change: number; icon: React.ComponentType<{ className?: string }> }) {')
