ccm.append('}')
ccm.append('')
ccm.append('const shipments = Array.from({ length: 55 }, (_, i) => {')
ccm.append('  const seed = i * 193 + 77')
ccm.append('  const product = pick(PRODUCT_TYPES, seed)')
ccm.append('  const coldType = pick(COLD_TYPES, seed + 1)')
ccm.append('  const tempRanges: Record<string, [number, number]> = { chilled: [2, 8], frozen: [-25, -15], ambient_controlled: [15, 25], deep_frozen: [-40, -20], ultra_cold: [-80, -60] }')
ccm.append('  const [tMin, tMax] = tempRanges[coldType]')
ccm.append('  const currentTemp = ri(tMin - 5, tMax + 8, seed + 2)')
