ccm.append('    city: pick(CITIES, seed + 4), region: pick(REGIONS, seed + 5),')
ccm.append('    currentTemp, minTemp: tMin, maxTemp: tMax, band, deviation,')
ccm.append('    humidity: ri(25, 90, seed + 6), duration: ri(2, 72, seed + 7),')
ccm.append('    value: ri(50000, 500000, seed + 8), weight: ri(10, 5000, seed + 9),')
ccm.append('    sensorCount: ri(1, 6, seed + 10), alerts: band === "breach" ? ri(3, 15, seed + 11) : band === "critical" ? ri(1, 4, seed + 11) : 0')
