ccm.append('const monthlyData = MO.map((m, i) => ({ month: m, shipments: ri(180, 350, i * 11 + 1), breaches: ri(0, 8, i * 11 + 2), compliance: ri(92, 99, i * 11 + 3), cost: ri(200, 600, i * 11 + 4) }))')
