ccm.append('            <Card className="ccm-chart-card"><CardHeader className="pb-2"><CardTitle className="text-sm font-semibold">Monthly Cost (Lakh)</CardTitle></CardHeader><CardContent><BarChart data={monthlyData}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="month" tick={{ fontSize: 10 }} /><YAxis tick={{ fontSize: 10 }} /><Tooltip /><Bar dataKey="cost" fill={TH.pri} radius={[4, 4, 0, 0]} /></BarChart></CardContent></Card>')
ccm.append('          </div>')
