ccm.append('        <TabsContent value="insights">')
ccm.append('          <ModuleBreadcrumb items={[{ label: "Cold Chain" }, { label: "Insights" }]} />')
ccm.append('          <div className="grid grid-cols-2 gap-4">')
ccm.append('            <Card className="ccm-insight-card border-l-4 border-l-cyan-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><Thermometer className="w-4 h-4 text-cyan-600" /><span className="font-semibold text-sm">Vaccine Cold Chain Risk</span></div><p className="text-xs text-gray-600 dark:text-gray-400">Ultra-cold vaccine shipments show 4% higher deviation rates during Mumbai-Chennai corridor. Pre-conditioning at origin hub recommended for improved stability.</p></CardContent></Card>')
ccm.append('            <Card className="ccm-insight-card border-l-4 border-l-red-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><AlertTriangle className="w-4 h-4 text-red-600" /><span className="font-semibold text-sm">Breach Hotspots</span></div><p className="text-xs text-gray-600 dark:text-gray-400">3 consecutive breaches detected on Delhi NCR frozen meat route. Root cause: door seal failure on reefer truck RF-204. Immediate inspection required.</p></CardContent></Card>')
ccm.append('            <Card className="ccm-insight-card border-l-4 border-l-emerald-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><CheckCircle2 className="w-4 h-4 text-emerald-600" /><span className="font-semibold text-sm">Sensor Network Growth</span></div><p className="text-xs text-gray-600 dark:text-gray-400">IoT sensor coverage reached 96% of active cold chain routes. Real-time monitoring resolution improved to 30-second intervals across all zones.</p></CardContent></Card>')
ccm.append('            <Card className="ccm-insight-card border-l-4 border-l-blue-500"><CardContent className="p-4"><div className="flex items-center gap-2 mb-2"><Snowflake className="w-4 h-4 text-blue-600" /><span className="font-semibold text-sm">Seasonal Demand</span></div><p className="text-xs text-gray-600 dark:text-gray-400">Fresh produce cold chain demand expected to increase 25% in August-September. Pre-position additional reefer capacity at Hyderabad and Chennai hubs.</p></CardContent></Card>')
ccm.append('          </div>')
ccm.append('        </TabsContent>')
ccm.append('      </Tabs>')
ccm.append('    </div>')
ccm.append('  )')
ccm.append('}')
